// Spider-Man poseable figure — anthropometric design table (pure data, mm).
// Frame: Z up, figure faces -Y, character LEFT = +X. Rest pose = T-pose, palms down.
// Right side is generated by mirroring X; rotation axes mirror as (ax,-ay,-az) so that a positive
// angle means the same anatomical motion on both sides.
export type V3=[number,number,number];
export type Plane='XY'|'YZ'|'XZ';
/** One cross-section. `at` = coordinate along the plane normal; c = centre in (u,v);
 *  a = [-u,+u] half extents, b = [-v,+v] half extents; n = superellipse exponent; bumps = [deg, amp, widthDeg].
 *  (u,v) = XY:(x,y) · YZ:(y,z) · XZ:(x,z). Angle 0 = +u, 90 = +v. */
export type Sec={at:number;c:[number,number];a:[number,number];b:[number,number];n?:number;bumps?:[number,number,number][];flatV?:number};

export const H=1780;           // stature
export const HEAD=230;         // vertex–menton → 7.74 heads (heroic-athletic canon)

/** Anatomical landmarks (left side, world). */
export const LM={
  vertex:1780, menton:1550, neckBase:[0,25,1465] as V3, atlas:[0,20,1592] as V3,
  thorax:[0,32,1200] as V3, lumbar:[0,28,1030] as V3, pelvis:[0,5,930] as V3,
  sc:[24,-48,1455] as V3, shoulder:[185,10,1435] as V3, elbow:[485,10,1435] as V3, wrist:[735,10,1435] as V3,
  hip:[90,0,925] as V3, knee:[88,0,495] as V3, ankle:[84,12,85] as V3, mtp:[88,-140,20] as V3,
};

const S=(at:number,c:[number,number],a:[number,number],b:[number,number],extra:Partial<Sec>={}):Sec=>({at,c,a,b,...extra});

