/** torso red panel half-width w(z): full-width above the armpit, tapering V to the belt. */
export function torsoRedHalfWidth(z:number){
  if(z>=1392)return 400;
  if(z<=1000)return 52;
  const t=(z-1000)/(1392-1000);return 52+(128-52)*Math.pow(t,1.35);
}
